const commits = items[0].json || [];
const closedIssues = items[1].json || [];
const closedPRs = items[2].json || [];
const mergedPRs = closedPRs.filter(pr => pr.merged_at !== null);
const formatDate = (dateStr) => new Date(dateStr).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
return [{ json: {
  repo: $parameter.githubRepo,
  period: { start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], end: new Date().toISOString().split('T')[0] },
  stats: { commits: commits.length, closedIssues: closedIssues.length, mergedPRs: mergedPRs.length },
  commits: commits.map(c => ({ sha: c.sha.substring(0,7), message: c.commit.message.split('\n')[0], author: c.commit.author.name, date: formatDate(c.commit.author.date), url: c.html_url })),
  issues: closedIssues.map(i => ({ number: i.number, title: i.title, author: i.user.login, closedAt: formatDate(i.closed_at), url: i.html_url })),
  mergedPRs: mergedPRs.map(pr => ({ number: pr.number, title: pr.title, author: pr.user.login, mergedAt: formatDate(pr.merged_at), url: pr.html_url }))
}]

